#include <cstdio>
#include <algorithm>
#include <cstring>
using namespace std;

const int MAX_VAL = 20000; // Adjust based on expected input range

int main() {
    int n, s, r[20200];
    while (scanf("%d %d", &n, &s) == 2 && n) {
        memset(r, 0, sizeof(r)); // Ensure array is zeroed
        for (int i = 0; i < n; i++) scanf("%d", &r[i]);

        // Counting sort for small ranges
        int count[MAX_VAL + 1] = {0};
        for (int i = 0; i < n; i++) {
            count[r[i]]++;
        }

        int index = 0;
        for (int i = 0; i <= MAX_VAL; i++) {
            while (count[i]--) {
                r[index++] = i;
            }
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            ans += n - (upper_bound(r + i + 1, r + n, s - r[i]) - r);
        }
        printf("%d\n", ans);
    }
}

